import re, doctest, sys, io, datetime
sys.path.insert(0, '/dateutil')
src = open('/dateutil/docs/examples.rst').read()
lines = src.split('\n')
blocks = []
i = 0
while i < len(lines):
    m = re.match(r'^\.\. (testsetup|testcode|doctest)::\s*(\S*)\s*$', lines[i])
    if m:
        kind, name = m.group(1), m.group(2)
        i += 1
        body = []
        while i < len(lines) and (lines[i].startswith('    :') or lines[i].strip() == ''):
            i += 1
        while i < len(lines) and (lines[i].startswith('    ') or lines[i].strip() == ''):
            body.append(lines[i][4:] if lines[i].startswith('    ') else '')
            i += 1
        blocks.append((kind, name, '\n'.join(body)))
    else:
        i += 1
globs = {}
setup = '\n'.join(b for k,n,b in blocks if k=='testsetup')
exec(compile(setup, 'testsetup', 'exec'), globs)
parser = doctest.DocTestParser()
norm = lambda s: re.sub(r'\s+', ' ', s).strip()
real = []
for k,n,b in blocks:
    if k in ('doctest','testcode'):
        test = parser.get_doctest(b, globs, f'{k}:{n}', 'examples.rst', 0)
        for ex in test.examples:
            if not ex.want: continue
            try:
                got = eval(compile(ex.source, '<ex>', 'eval'), globs)
            except SyntaxError:
                exec(compile(ex.source, '<ex>', 'exec'), globs); continue
            except Exception as e:
                got = f'{type(e).__name__}: {e}'
            g = norm(repr(got)); w = norm(ex.want)
            if g != w:
                real.append((n, ex.source.strip(), w, g))
print("REAL MISMATCHES:", len(real))
for n, s, w, g in real:
    print(f'--- [{n}] {s}\n  want: {w}\n  got : {g}')
