cd /dateutil && python3 - <<'PY'
import ast, sys
for f in ['dateutil/relativedelta.py','dateutil/rrule.py','dateutil/parser.py','dateutil/_common.py','dateutil/tz/tz.py','dateutil/tz/_common.py','dateutil/easter.py']:
    src=open(f).read()
    tree=ast.parse(src)
    imported=set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names: imported.add((a.asname or a.name).split('.')[0])
        elif isinstance(n, ast.ImportFrom):
            for a in n.names: imported.add(a.asname or a.name)
    names={n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    # also attribute bases
    for n in ast.walk(tree):
        if isinstance(n, ast.Attribute):
            b=n
            while isinstance(b, ast.Attribute): b=b.value
            if isinstance(b, ast.Name): names.add(b.id)
    unused = sorted(i for i in imported if i not in names and i not in src.split('__all__')[-1])
    print(f, "possibly unused imports:", unused)
