for f in sorted(glob.glob('dateutil/**/*.py', recursive=True)):
    if '/test' in f: continue
    tree = ast.parse(open(f).read())
    for cls in [n for n in ast.walk(tree) if isinstance(n, ast.ClassDef)]:
