import sys, trace, os, io, ast, importlib, glob
sys.path.insert(0,'/dateutil')
import unittest
mods = ['dateutil.test.test_relativedelta','dateutil.test.test_rrule','dateutil.test.test_parser',
        'dateutil.test.test_tz','dateutil.test.test_easter','dateutil.test.test_imports']
loaded = [importlib.import_module(m) for m in mods]
tracer = trace.Trace(count=1, trace=0, ignoredirs=[sys.prefix, sys.exec_prefix])
def run():
    suite = unittest.TestSuite([unittest.TestLoader().loadTestsFromModule(m) for m in loaded])
    unittest.TextTestRunner(stream=io.StringIO(), verbosity=0).run(suite)
tracer.runfunc(run)
counts = tracer.results().counts
executed = {}
for (f,l) in counts:
    executed.setdefault(os.path.abspath(f), set()).add(l)
for f in sorted(glob.glob('/dateutil/dateutil/**/*.py', recursive=True)):
    if '/test' in f: continue
    src = open(f).read().split('\n')
    tree = ast.parse('\n'.join(src))
    # collect statements inside functions with their indent
    missing = []
    for fn in [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)]:
        for n in ast.walk(fn):
            if isinstance(n, ast.stmt) and not isinstance(n,(ast.FunctionDef,ast.ClassDef)):
                if isinstance(n, ast.Expr) and isinstance(n.value, ast.Str):
                    continue  # docstring
                if n.lineno not in executed.get(f, set()):
                    missing.append(n.lineno)
    missing = sorted(set(missing))
    if missing:
        print(f"== {f}: {len(missing)} uncovered statements in functions")
        for l in missing:
            print(f"   {l}: {src[l-1][:110]}")
